DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

Context("Point");
do {
  @a = random_subset(4, -5 .. 5)
} until (min(@a) < 0 && max(@a) > 0);
$A = Point((@a)[0,1]);
$B = Point((@a)[2,3]);
Context("Fraction");
$m = Fraction($a[3] - $a[1], $a[2] - $a[0]);
Context()->flags->set(reduceConstants => 0);
$top = Formula("x - $a[1]");
$top = $top->substitute(x => $a[3]);
$bottom = Formula("x - $a[0]");
$bottom = $bottom->substitute(x => $a[2]);

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}[
      xmin=-6,
      ymin=-6,
      xmax=6,
      ymax=6,
      xtick=,
      ytick=,
      minor xtick=,
      minor ytick=,
      width=0.47\orccaprintwidth,
    ]
    \addplot[soliddot] coordinates {$A $B};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

######
# Body
######

BEGIN_PGML
>> [@image(insertGraph($image_1), width=>282)@]*  <<

[_]{$m}{5}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
The coordinates of the points are [`[$A]`] and [`[$B]\text{.}`] We apply the rate of change formula:

[```
\begin{aligned}
\amp\frac{y_2-y_1}{x_2-x_1}\\
\amp= \frac{[$top]}{[$bottom]}\\
\amp= \frac{[$top->reduce]}{[$bottom->reduce]}
\end{aligned}
```]

So the rate of change is [`[$m]\text{.}`]

END_PGML_SOLUTION

#############
# End Problem
#############

ENDDOCUMENT();
